/**
 * @summary Search known cities (OSM-seeded reference data)
 */
export const getListCitiesUrl = (params?: ListCitiesParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/cities?${stringifiedParams}`
    : `/api/cities`;
};

export const listCities = async (
  params?: ListCitiesParams,
  options?: RequestInit,
): Promise<CitiesEnvelope> => {
  return customFetch<CitiesEnvelope>(getListCitiesUrl(params), {
    ...options,
    method: "GET",
  });
};

